const moment = global.get("moment");
const now = moment().add(7, 'hours');

// Lấy dữ liệu từ flow
let inputRegisterData = global.get('inputRegisterData');
let holdingRegisterData = global.get('holdingRegisterData');
let coilRegisterData = global.get('coilRegisterData');  // Thêm dữ liệu từ coilRegisterData để kiểm tra trạng thái máy


// Lấy giá trị lưu lượng tổng từ inputRegisterData
let volumeData = {
    A1: inputRegisterData.volume_A1,
    B1: inputRegisterData.volume_B1,
    B2: inputRegisterData.volume_B2,
    A2: inputRegisterData.volume_A2,
    A3: inputRegisterData.volume_A3,
    B3: inputRegisterData.volume_B3
};

// Lấy giá trị lưu lượng đặt từ holdingRegisterData (trên phút)
let setFlowData = {
    A1: holdingRegisterData.set_flow_A1,
    B1: holdingRegisterData.set_flow_B1,
    B2: holdingRegisterData.set_flow_B2,
    A2: holdingRegisterData.set_flow_A2,
    A3: holdingRegisterData.set_flow_A3,
    B3: holdingRegisterData.set_flow_B3
};

//irri time count in second from device
let irriTimeCountCountDown = inputRegisterData.set_irrigation_time_count

let timeValveData = {
    A1: holdingRegisterData.time_valve_A1,
    B1: holdingRegisterData.time_valve_B1,
    B2: holdingRegisterData.time_valve_B2,
    A2: holdingRegisterData.time_valve_A2,
    A3: holdingRegisterData.time_valve_A3,
    B3: holdingRegisterData.time_valve_B3
};


// Tính sai số cho phép
const toleranceRunning = 0.2;
const toleranceStopped = 0.03;
let errMapping = global.get("modbusErrMap");
let errQueue = global.get("errorQueue") || [];

// Kiểm tra trạng thái của máy dựa trên các thanh ghi
let isMachineRunning = coilRegisterData.main_pump == 1 || coilRegisterData.power == 1;  // Kiểm tra các thanh ghi chính
// let isMachineRunning = global.get("test_state")
let previousMachineState = context.get('previousMachineState') || false;

// Nếu máy bắt đầu chạy, lấy previousTimestamp và bắt đầu đếm thời gian chạy
let currentTimestamp = now.valueOf();
let previousTimestamp = context.get('previousTimestamp') || currentTimestamp;
let elapsedRunTime = context.get('elapsedRunTime') || 0;
let lastErrorTime = context.get('lastErrorTime') || 0;

function resetMachineState() {
    // node.warn("Máy không chạy, đặt lại thời gian theo dõi.");
    context.set('previousTimestamp', null);
    context.set('elapsedRunTime', 0);
    context.set('previousMachineState', isMachineRunning);
}

function checkInitialFlow(channel, actualVolume, setFlow, elapsedTimeMinutes) {
    let expectedVolume = setFlow * elapsedTimeMinutes;
    let lowerBound = expectedVolume * 0.8;  // 80% lưu lượng mong đợi

    if (actualVolume < lowerBound) {
        node.warn(`Cảnh báo: Lưu lượng kênh ${channel} nhỏ hơn 80% lưu lượng mong đợi. Đang dừng bơm.`);
        stopPump();
        node.warn("stop Pump xong sẽ in hàm này")
        let errors = []
        errors.push(create1stMinuteFlowError(channel, actualVolume, expectedVolume, elapsedTimeMinutes))
        // Kiểm tra nếu có lỗi và thời gian vượt qua debouncing
        if (errors.length > 0 && shouldLogError(lastErrorTime, currentTimestamp)) {
            errors.forEach(error => errQueue.push(error));
            global.set("errorQueue", errQueue);
            node.warn("Phát hiện lỗi và đã đẩy vào hàng đợi errorQueue.");
            context.set('lastErrorTime', currentTimestamp);
        } else if (errors.length > 0) {
            node.warn("Phát hiện lỗi nhưng đang đợi hết thời gian chờ debouncing.");
        } else {
            node.warn("Tất cả các giá trị lưu lượng đều nằm trong khoảng cho phép.");
        }
        return true;  // Trả về true nếu cần dừng bơm
    }
    return false;
}

function stopPump() {
    const modbusCoils = global.get("modbusCoils");
    const coilsToTurnOff = ['power'];
    for (let coil of coilsToTurnOff) {
        if (modbusCoils.hasOwnProperty(coil)) {
            let address = modbusCoils[coil];
            msg.payload = {
                'value': 0,
                'fc': 5,
                'unitid': 1,
                'address': address,
                'quantity': 1
            };
            node.send(msg);
        }
    }
}

function createFlowError(channel, actualFlow, expectedFlow, elapsedTimeMinutes) {
    let errorCode = "F4";
    let errorMessage = errMapping[errorCode]?.description || "Lỗi lưu lượng";

    // Làm tròn các số đến 2 chữ số thập phân
    actualFlow = Math.round(actualFlow * 100) / 100;
    expectedFlow = Math.round(expectedFlow * 100) / 100;
    elapsedTimeMinutes = Math.round(elapsedTimeMinutes * 100) / 100;

    return {
        type: "device_err",
        severity: "alarm",
        device_label: global.get("device_label"),
        error_code: errorCode,
        error_message: `${errorMessage} Kênh ${channel}: Thực tế ${actualFlow}, Mong đợi ${expectedFlow}, Thời gian ${elapsedTimeMinutes} phút`,
        ts: now.format('YYYY-MM-DD HH:mm:ss')
    };
}


function create1stMinuteFlowError(channel, actualFlow, expectedFlow, elapsedTimeMinutes) {
    let errorCode = "F5";
    let errorMessage = errMapping[errorCode]?.description || "Lỗi lọt khí hoặc hết phân";

    // Làm tròn các số đến 2 chữ số thập phân
    actualFlow = Math.round(actualFlow * 100) / 100;
    expectedFlow = Math.round(expectedFlow * 100) / 100;
    elapsedTimeMinutes = Math.round(elapsedTimeMinutes * 100) / 100;

    return {
        type: "device_err",
        severity: "alarm",
        device_label: global.get("device_label"),
        error_code: errorCode,
        error_message: `${errorMessage}. Lưu lượng Kênh ${channel}: Thực tế ${actualFlow}, Mong đợi ${expectedFlow}, Thời gian ${elapsedTimeMinutes} phút`,
        ts: now.format('YYYY-MM-DD HH:mm:ss')
    };
}

function checkFlow(channel, actualVolume, setFlow, elapsedTimeMinutes, tolerance) {
    //làm tròn 1 chữ số thập phân
    const roundedElapsedTime = Math.round(elapsedTimeMinutes * 10) / 10;

    node.warn(`Kiểm tra lưu lượng cho kênh ${channel}`);
    node.warn(`Giá trị thực tế: ${actualVolume}`);
    node.warn(`Lưu lượng đặt: ${setFlow}`);
    node.warn(`Thời gian đã trôi qua (phút): ${roundedElapsedTime}`);
    node.warn(`Sai số cho phép: ${tolerance}`);

    let expectedVolume = setFlow * roundedElapsedTime;
    node.warn(`Lưu lượng mong đợi: ${expectedVolume}`);

    let lowerBound = expectedVolume * (1 - tolerance);
    let upperBound = expectedVolume * (1 + tolerance);
    node.warn(`Khoảng cho phép: [${lowerBound}, ${upperBound}]`);

    node.warn(`Kênh ${channel}: Thực tế ${actualVolume}, Mong đợi ${expectedVolume}, Khoảng cho phép: [${lowerBound}, ${upperBound}]`);

    if (actualVolume < lowerBound || actualVolume > upperBound) {
        node.warn(`Lưu lượng kênh ${channel} nằm ngoài khoảng cho phép.`);
        return createFlowError(channel, actualVolume, expectedVolume, roundedElapsedTime);
    }
    node.warn(`Lưu lượng kênh ${channel} nằm trong khoảng cho phép.`);
    return null;
}

function shouldLogError(lastErrorTime, currentTime, debounceMinutes = 3) {
    let elapsedMinutes = (currentTime - lastErrorTime) / 60000;
    return elapsedMinutes >= debounceMinutes;
}

function checkFlowWithToleranceWhenFinish(tolerance) {
    let errors = [];

    for (let channel in volumeData) {
        // Chỉ kiểm tra những kênh có setFlowData khác 0
        if (setFlowData[channel] !== 0) {
            // Tính toán thời gian thực tế từ device
            let actualIrriTimeMinutes = (timeValveData[channel] - irriTimeCountCountDown) / 60;

            // Chỉ kiểm tra nếu thời gian tưới thực tế > 0
            if (actualIrriTimeMinutes > 0) {
                let error = checkFlow(
                    channel,
                    volumeData[channel],
                    setFlowData[channel],
                    actualIrriTimeMinutes,
                    tolerance
                );
                if (error) errors.push(error);
            }
        }
    }

    if (errors.length > 0 && shouldLogError(lastErrorTime, currentTimestamp)) {
        errors.forEach(error => errQueue.push(error));
        global.set("errorQueue", errQueue);
        node.warn("Phát hiện lỗi và đã đẩy vào hàng đợi errorQueue.");
        context.set('lastErrorTime', currentTimestamp);
    } else if (errors.length > 0) {
        node.warn("Phát hiện lỗi nhưng đang đợi hết thời gian chờ debouncing.");
    } else {
        node.warn("Tất cả các giá trị lưu lượng đều nằm trong khoảng cho phép.");
    }
}


