if (!isMachineRunning) {
    if (previousMachineState) {
        // Máy vừa tắt, kiểm tra với tolerance thấp hơn
        node.warn("Máy vừa tắt, kiểm tra lưu lượng với tolerance thấp hơn.");
        checkFlowWithToleranceWhenFinish(toleranceStopped);
    }
    resetMachineState();
    return null;
}

// Tính thời gian đã trôi qua (tính bằng phút)
let timeSinceLastCheck = (currentTimestamp - previousTimestamp) / 60000;
elapsedRunTime += timeSinceLastCheck;

// Lưu giá trị timestamp hiện tại cho lần tiếp theo
context.set('previousTimestamp', currentTimestamp);

// Chỉ kiểm tra lỗi nếu máy đã chạy đủ thời gian tối thiểu (ví dụ: 1 phút)
if (elapsedRunTime < 1) {
    node.warn(`Máy đã chạy được ${elapsedRunTime.toFixed(2)} phút. Đang đợi ít nhất 1 phút.`);
    context.set('elapsedRunTime', elapsedRunTime);
    context.set('previousMachineState', isMachineRunning);
    return null;
} else if (elapsedRunTime < 1.5) {
    node.warn(`Máy đã chạy được ${elapsedRunTime.toFixed(2)} phút. Đang kiểm tra lưu lượng phút đầu tiên.`);

    // Kiểm tra các kênh trong phút đầu tiên
    for (let channel in volumeData) {
        // Chỉ kiểm tra những kênh có cấu hình setFlow và time
        if (setFlowData[channel] > 0 && timeValveData[channel] > 0) {
            checkInitialFlow(channel, volumeData[channel], setFlowData[channel], elapsedRunTime);
        }
    }

    context.set('elapsedRunTime', elapsedRunTime);
    context.set('previousMachineState', isMachineRunning);
    return null;
}

// Kiểm tra lưu lượng với tolerance khi máy đang chạy
// checkFlowWithToleranceWhenRunning(toleranceRunning); //tạm tắt, chỉ kiểm tra lúc chạy xong

// Lưu thời gian chạy máy để kiểm tra sau
context.set('elapsedRunTime', elapsedRunTime);
context.set('previousMachineState', isMachineRunning);

